<?php
require __DIR__.'/auth.php';requireUnitManager();require __DIR__.'/app_ui.php';require __DIR__.'/workday_lib.php';require __DIR__.'/leave_transfer_lib.php';
$p=db();$config=lt_config();$unit=$config['facility_code'];if(isStaff()&&currentFacilityCode()!==$unit){http_response_code(403);exit('ชุดนี้ได้รับอนุญาตเฉพาะหน่วย '.$unit);}
$fy=max(2500,min(2700,(int)($_GET['fy']??2570)));$s=$p->prepare('SELECT id,full_name,facility_code FROM compensation_personnel WHERE active=1 AND facility_code=? ORDER BY full_name');$s->execute([$unit]);$people=$s->fetchAll();$pid=(int)($_GET['pid']??($people[0]['id']??0));$person=lt_person($p,$pid);$s=$p->prepare("SELECT uuid FROM compensation_transfer_map WHERE kind='person' AND local_key=?");$s->execute([(string)$pid]);$uuid=$s->fetchColumn();$month=$_GET['month']??wd_months($fy)[0];if(!in_array($month,wd_months($fy),true))$month=wd_months($fy)[0];$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{verifyAuthCsrf();$s=$p->prepare('SELECT * FROM compensation_unit_calendars WHERE facility_code=? AND month_start=?');$s->execute([$unit,$month]);$old=$s->fetch();if(!$old)throw new RuntimeException('เดือนนี้ยังไม่มีปฏิทินรายหน่วย ให้รับแฟ้มปฏิทินก่อน');if((int)($_POST['revision']??0)!==(int)$old['revision'])throw new RuntimeException('มีผู้แก้ก่อนแล้ว กรุณาโหลดใหม่');$overrides=[];$d=new DateTimeImmutable($month);while($d->format('Y-m')===substr($month,0,7)){$date=$d->format('Y-m-d');$holiday=isset($_POST['holiday'][$date]);$label=trim($_POST['label'][$date]??'');if(mb_strlen($label)>200)throw new RuntimeException('หมายเหตุยาวเกิน');if($holiday!==((int)$d->format('N')>=6)||$label!=='')$overrides[$date]=['is_holiday'=>$holiday,'label'=>$label];$d=$d->modify('+1 day');}$changed=!lt_equal(json_decode($old['overrides_json']), (object)$overrides);$verified=!$changed&&isset($_POST['checked']);$s=$p->prepare('UPDATE compensation_unit_calendars SET overrides_json=?,verified=?,revision=revision+1,updated_by=?,verified_by=?,verified_at=? WHERE facility_code=? AND month_start=? AND revision=?');$actor=(int)currentUser()['id'];$s->execute([lt_json((object)$overrides),(int)$verified,$actor,$verified?$actor:null,$verified?date('Y-m-d H:i:s'):null,$unit,$month,$old['revision']]);if(!$s->rowCount())throw new RuntimeException('ข้อมูลเปลี่ยน กรุณาตรวจใหม่');$notice=$changed?'บันทึกเป็นร่างแล้ว ต้องเปิดตรวจและยืนยันอีกครั้ง':($verified?'ยืนยันปฏิทินรายหน่วยแล้ว':'บันทึกปฏิทินร่างแล้ว');}catch(Throwable $e){$notice=$e->getMessage();}}
$s=$p->prepare('SELECT * FROM compensation_unit_calendars WHERE facility_code=? AND month_start=?');$s->execute([$unit,$month]);$calendar=$s->fetch();$overrides=$calendar?json_decode($calendar['overrides_json'],true):[];
function lt_e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>รับส่งทะเบียนลา · local</title><link rel="stylesheet" href="assets/style.css"><style>dialog{max-width:850px;width:90%;max-height:85vh;overflow:auto;border:1px solid #ccc;border-radius:12px;padding:24px}dialog input:not([type=checkbox]){display:block;width:95%;margin:8px 0}dialog form{margin:20px 0}#transfer-error{color:#b42318}#transfer-history{white-space:pre-wrap}button{cursor:pointer}</style></head><body class="has-sidebar"><?php ui_sidebar('work-leave');?><main class="container"><section class="panel"><h1>รับส่งทะเบียนลา · local</h1><p>ชุดที่ผู้เขียนอนุญาต: <?=lt_e($config['instance'])?> · หน่วย <?=lt_e($unit)?> · ไม่มีการซิงค์</p><p>STAFF เป็นผู้บันทึกและจัดทำเอกสารของหน่วย การอนุมัติราชการต้องลงนามจริงและบันทึกแยกจากผู้บันทึก</p><form method="get"><label>บุคลากร<select name="pid"><?php foreach($people as $x):?><option value="<?=$x['id']?>" <?=$pid==(int)$x['id']?'selected':''?>><?=lt_e($x['full_name'])?></option><?php endforeach;?></select></label><label>ปีงบประมาณ<input type="number" name="fy" value="<?=$fy?>" min="2500" max="2700"></label><label>เดือน<select name="month"><?php foreach(wd_months($fy) as $m):?><option <?=$m===$month?'selected':''?>><?=$m?></option><?php endforeach;?></select></label><button>แสดง</button></form><p>UUID cloud: <?=lt_e($uuid?:'ยังไม่ได้เชื่อม')?></p><?php if(!$uuid&&isAdmin()):?><form id="map-person"><label>UUID จากทะเบียนบุคลากร cloud<input name="uuid" required></label><label><input name="identity_checked" type="checkbox" required> ตรวจว่า UUID เป็นบุคลากรรายนี้และหน่วยเดียวกันแล้ว</label><button>เชื่อมครั้งแรก</button><p id="mapping-error" role="alert"></p></form><?php endif;?><?php if($uuid):?><button data-transfer-open>ส่งออก / นำเข้า</button><?php endif;?><p><a href="work_leave.php?fy=<?=$fy?>&personnel_id=<?=$pid?>">กลับทะเบียนลา</a></p></section><section class="panel"><h2>ปฏิทินรายหน่วย <?=$month?></h2><p><?=lt_e($notice)?></p><?php if($calendar):?><form method="post"><input type="hidden" name="csrf" value="<?=lt_e(authCsrfToken())?>"><input type="hidden" name="revision" value="<?=$calendar['revision']?>"><p><?=$calendar['verified']?'ยืนยันแล้ว':'รอยืนยัน'?> · แก้วันหยุดแล้วจะกลับเป็นร่าง ไม่เปลี่ยนปฏิทินของหน่วยอื่น</p><table><thead><tr><th>วันที่</th><th>วันหยุด</th><th>ชื่อ/หมายเหตุ</th></tr></thead><tbody><?php $d=new DateTimeImmutable($month);while($d->format('Y-m')===substr($month,0,7)):$date=$d->format('Y-m-d');$o=$overrides[$date]??['is_holiday'=>(int)$d->format('N')>=6,'label'=>''];?><tr><td><?=$date?></td><td><input type="checkbox" name="holiday[<?=$date?>]" <?=$o['is_holiday']?'checked':''?>></td><td><input name="label[<?=$date?>]" maxlength="200" value="<?=lt_e($o['label'])?>"></td></tr><?php $d=$d->modify('+1 day');endwhile;?></tbody></table><label><input type="checkbox" name="checked"> ตรวจประกาศวันหยุดของหน่วยครบแล้ว</label><button>บันทึก / ยืนยัน</button></form><?php else:?><p>ยังไม่มีปฏิทินรับเข้ารายหน่วย เดือนนี้ใช้ปฏิทิน local เดิมจนกว่าจะรับแฟ้มของเดือนนี้</p><?php endif;?></section></main><dialog id="transfer-dialog"><button id="transfer-close">ปิด</button><h2 id="transfer-title"></h2><div id="transfer-body"></div></dialog><script type="module">
import {createTransferUI} from './assets/leave-transfer/transfer-ui.js';
const c=<?=json_encode(['userId'=>(string)currentUser()['id'],'admin'=>isAdmin(),'manager'=>true,'year'=>$fy,'person'=>['id'=>$uuid?:'','facility_code'=>$unit,'full_name'=>$person['full_name']]],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
const csrf=<?=json_encode(authCsrfToken())?>;
async function api(action,body={}){const r=await fetch('leave_transfer_api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,csrf,pid:<?=$pid?>,fy:c.year,...body})});const result=await r.json();if(!r.ok)throw new Error(result.error||'รับส่งข้อมูลไม่สำเร็จ');return result;}
const dialog=document.getElementById('transfer-dialog');document.getElementById('transfer-close').onclick=()=>dialog.close();
createTransferUI({getContext:()=>c,openDialog:(title,html)=>{document.getElementById('transfer-title').textContent=title;document.getElementById('transfer-body').innerHTML=html;dialog.showModal();},adapter:{receipt:package_id=>api('receipt',{package_id}),snapshot:()=>api('snapshot'),preview:packet=>api('plan',{packet}),apply:(packet,expected_token,selected)=>api('apply',{packet,expected_token,selected}),history:()=>api('history')}});
document.getElementById('map-person')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api('map',{uuid:new FormData(e.target).get('uuid'),identity_checked:true});location.reload();}catch(error){document.getElementById('mapping-error').textContent=error.message;}finally{button.disabled=false;}});
</script><?php ui_footer();?></body></html>
